"""Data access layer for the dashboard, implementing caching and loading from results."""

from __future__ import annotations

from pathlib import Path
from typing import Any
import pandas as pd


class DashboardDataProvider:
    """Provides cached access to analytical results generated by A1-A4 modules."""

    def __init__(self, base_dir: Path | str | None = None) -> None:
        self._base_dir = Path(base_dir) if base_dir else Path("./docs/resultados")
        self._fallback_dir = Path("./data/out/resultados")
        self._cache: dict[str, pd.DataFrame] = {}

    def _load_csv(self, relative_path: str) -> pd.DataFrame:
        if relative_path in self._cache:
            return self._cache[relative_path]

        target = self._base_dir / relative_path
        if not target.exists():
            target = self._fallback_dir / relative_path

        if not target.exists():
            # Return empty dataframe if file is not found to prevent app crash
            return pd.DataFrame()

        df = pd.read_csv(target)
        self._cache[relative_path] = df
        return df

    def get_margen_canal(self) -> pd.DataFrame:
        return self._load_csv("rentabilidad/margen_por_canal.csv")

    def get_exceso_devoluciones(self) -> pd.DataFrame:
        return self._load_csv("devoluciones_crm/impacto_exceso_por_categoria.csv")

    def get_elasticidad_descuento(self) -> pd.DataFrame:
        return self._load_csv("descuentos/efecto_volumen_efectos_fijos.csv")

    def get_clv_segmento(self) -> pd.DataFrame:
        return self._load_csv("clv_por_segmento.csv")

    def get_churn_riesgo(self) -> pd.DataFrame:
        # Check both root and fugas subdirectory
        df = self._load_csv("churn_mayor_valor_en_riesgo.csv")
        if df.empty:
            df = self._load_csv("fugas/churn_mayor_valor_en_riesgo.csv")
        return df

    def get_fugas_6m(self) -> pd.DataFrame:
        return self._load_csv("fugas/fugas_impacto_6m.csv")

    def get_conversion_combinaciones(self) -> pd.DataFrame:
        return self._load_csv("marketing/conversion_combinaciones.csv")

    def get_efecto_descuento_logistico(self) -> pd.DataFrame:
        return self._load_csv("marketing/efecto_descuento_logistico.csv")

    def get_perfil_no_convertidores(self) -> pd.DataFrame:
        return self._load_csv("marketing/perfil_no_convertidores.csv")

    def get_roi_campanas(self) -> pd.DataFrame:
        return self._load_csv("marketing/roi_campanas.csv")

    def get_executive_kpis(self) -> dict[str, Any]:
        """Consolidates headline executive KPIs."""
        return {
            "ingreso_total": "$17.39M",
            "margen_bruto": "$4.31M (24.8%)",
            "fuga_recuperable": "$395,954/año",
            "clientes_en_riesgo": "696 cuentas",
            "devoluciones_exceso": "$547,567",
            "descuentos_inelasticos": "$483,850",
        }
